<?php
declare(strict_types=1);
/**
 * install_admin_paid_payouts_render_v003_20261115_090400pm.php
 *
 * VERSION: v003
 * LAST MODIFIED: 11/15/2026 9:04 pm ET
 *
 * PURPOSE:
 * - Replace only /public_html/admin_paid_payouts.php with the simplified v003 render layer.
 * - Preserve admin_paid_payouts_helper.php, financial tables/data, payout engine, scoring,
 *   scheduler, snapshots, and all existing public payout pages.
 * - Hide POSTCHECK until Apply has actually run.
 *
 * PHP: 7.3 compatible.
 */

date_default_timezone_set('America/New_York');

$publicRoot = dirname(__DIR__);
$target = $publicRoot.'/admin_paid_payouts.php';
$backupRoot = $publicRoot.'/_installer_backups';
$PAGE_B64 = '';
$EXPECTED_SHA = 'a6138ef822618e81f1182e307b121fd95aa41a3e91957a619a091c00d458ccfc';
$stateFile = __DIR__.'/.install_admin_paid_payouts_render_v003_state.json';

function iv3_h($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function iv3_now(): string { return date('Y-m-d\TH:i:sP'); }
function iv3_lint(string $path): array {
    $cmd = 'php -l '.escapeshellarg($path).' 2>&1';
    $out = @shell_exec($cmd);
    $out = trim((string)$out);
    return [strpos($out,'No syntax errors detected') !== false, $out];
}
function iv3_write_atomic(string $path, string $content): void {
    $tmp = $path.'.tmp_'.getmypid().'_'.bin2hex(random_bytes(3));
    if (@file_put_contents($tmp,$content,LOCK_EX) === false) throw new RuntimeException('Could not write temporary file.');
    @chmod($tmp,0644);
    if (!@rename($tmp,$path)) { @unlink($tmp); throw new RuntimeException('Could not install target file.'); }
    @chmod($path,0644);
}
function iv3_save_state(string $path,array $state): void {
    @file_put_contents($path,json_encode($state,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));
}
function iv3_load_state(string $path): array {
    if (!is_file($path)) return [];
    $d=json_decode((string)@file_get_contents($path),true);
    return is_array($d)?$d:[];
}

$page = base64_decode($PAGE_B64,true);
$checks = [];

$checks[] = ['label'=>'Installer running from /public_html/_installers','ok'=>realpath(__DIR__)===realpath($publicRoot.'/_installers'),'detail'=>__DIR__];
$checks[] = ['label'=>'Existing root admin page exists','ok'=>is_file($target),'detail'=>$target];
$checks[] = ['label'=>'Root admin page writable','ok'=>is_writable(dirname($target)),'detail'=>dirname($target)];
$checks[] = ['label'=>'Helper remains present','ok'=>is_file($publicRoot.'/admin_paid_payouts_helper.php'),'detail'=>$publicRoot.'/admin_paid_payouts_helper.php'];
$checks[] = ['label'=>'Payout helper remains present','ok'=>is_file($publicRoot.'/race_results/payouts_helper.php'),'detail'=>$publicRoot.'/race_results/payouts_helper.php'];
$checks[] = ['label'=>'Embedded v003 page decoded','ok'=>is_string($page),'detail'=>is_string($page)?strlen($page).' bytes':'decode failed'];

$candidateLint=[false,'not run'];
if (is_string($page)) {
    $tmp=tempnam(sys_get_temp_dir(),'mrlapp_v3_');
    file_put_contents($tmp,$page);
    $candidateLint=iv3_lint($tmp);
    @unlink($tmp);
}
$checks[] = ['label'=>'Candidate v003 php -l','ok'=>$candidateLint[0],'detail'=>$candidateLint[1]];

$preOk = true;
foreach($checks as $c) if(!$c['ok']) $preOk=false;

$action = (string)($_POST['action'] ?? '');
$message = '';
$post = [];
$state = iv3_load_state($stateFile);

if ($action === 'apply' && $preOk) {
    try {
        if (!is_dir($backupRoot) && !@mkdir($backupRoot,0755,true) && !is_dir($backupRoot)) {
            throw new RuntimeException('Could not create backup root.');
        }
        $stamp=date('Ymd_His');
        $backupDir=$backupRoot.'/install_admin_paid_payouts_render_v003_'.$stamp;
        if (!@mkdir($backupDir,0755,true) && !is_dir($backupDir)) {
            throw new RuntimeException('Could not create backup folder.');
        }
        if (is_file($target) && !@copy($target,$backupDir.'/admin_paid_payouts.php')) {
            throw new RuntimeException('Could not back up current admin page.');
        }

        iv3_write_atomic($target,$page);

        [$lintOk,$lintOut]=iv3_lint($target);
        if (!$lintOk) {
            if (is_file($backupDir.'/admin_paid_payouts.php')) @copy($backupDir.'/admin_paid_payouts.php',$target);
            throw new RuntimeException('Installed file failed php -l; previous page restored. '.$lintOut);
        }

        $installedSha=hash_file('sha256',$target);
        if ($installedSha !== $EXPECTED_SHA) {
            if (is_file($backupDir.'/admin_paid_payouts.php')) @copy($backupDir.'/admin_paid_payouts.php',$target);
            throw new RuntimeException('Installed SHA mismatch; previous page restored.');
        }

        $state=['applied'=>true,'at'=>iv3_now(),'backup_dir'=>$backupDir];
        iv3_save_state($stateFile,$state);
        $message='PASS — v003 page installed. Open /admin_paid_payouts.php now.';
    } catch(Throwable $e) {
        $message='FAIL — '.$e->getMessage();
    }
    $state = iv3_load_state($stateFile);
}

if (!empty($state['applied'])) {
    $exists=is_file($target);
    [$lintOk,$lintOut]=$exists?iv3_lint($target):[false,'target missing'];
    $sha=$exists?hash_file('sha256',$target):'';
    $post=[
        ['label'=>'Root admin_paid_payouts.php exists','ok'=>$exists,'detail'=>$target],
        ['label'=>'Installed root page php -l','ok'=>$lintOk,'detail'=>$lintOut],
        ['label'=>'Installed SHA matches v003','ok'=>$sha===$EXPECTED_SHA,'detail'=>$sha],
        ['label'=>'Helper unchanged/present','ok'=>is_file($publicRoot.'/admin_paid_payouts_helper.php'),'detail'=>$publicRoot.'/admin_paid_payouts_helper.php'],
        ['label'=>'Payout helper unchanged/present','ok'=>is_file($publicRoot.'/race_results/payouts_helper.php'),'detail'=>$publicRoot.'/race_results/payouts_helper.php'],
    ];
}
